$stmt = $pdo->prepare('SELECT failed_attempts, locked_until FROM users WHERE email = ?');
$stmt->execute([$email]);
$user = $stmt->fetch();
if ($user['failed_attempts'] >= 5 && strtotime($user['locked_until']) > time()) {
    die('アカウントがロックされています。しばらく後に再試行してください。');
}

